print("Looking for edges with 1679091c5a as source:")
for line in edges_text.strip().split('\n'):
    if '1679091c5a' in line:
        print(f"  {line}")

print("\nLet me re-parse more carefully:")
graph2 = defaultdict(set)
lines = edges_text.strip().split('\n')
print(f"Total lines: {len(lines)}")

for i, line in enumerate(lines):
    line = line.strip()
    if ' -> ' in line:
        parts = line.split(' -> ')
        if len(parts) == 2:
            src, dst = parts[0].strip(), parts[1].strip()
            graph2[src].add(dst)
        else:
            print(f"Line {i} has weird format: {line}")

print(f"\nNeighbors of 1679091c5a: {sorted(graph2.get('1679091c5a', []))}")

# Re-run BFS with correct graph
queue = deque([(start_node, 0)])
distances2 = {start_node: 0}

while queue:
    node, dist = queue.popleft()
    for neighbor in graph2.get(node, []):
        if neighbor not in distances2:
            distances2[neighbor] = dist + 1
            queue.append((neighbor, dist + 1))

print(f"\nTotal nodes reachable from {start_node}: {len(distances2)}")

by_dist2 = defaultdict(list)
for node, dist in sorted(distances2.items(), key=lambda x: x[1]):
    by_dist2[dist].append(node)

for d in sorted(by_dist2.keys()):
    print(f"Distance {d}: {sorted(by_dist2[d])}")

print(f"\nNodes at exactly distance 4: {sorted(by_dist2.get(4, []))}")
